package dev.launcherfork.data.mock

import dev.launcherfork.domain.GameDescription
import dev.launcherfork.domain.Server
import dev.launcherfork.theme.Theme
import java.net.URI

/**
 * All placeholder content of the fork lives here: a single game, STALZONE. Its background art is generated by
 * tools/GenerateZoneArt.java. The sidebar mark is the stalker helmet ([Theme.GAME_ICON]), not the frost window mark
 * and not the old radiation favicon.
 */
object MockData {
    private const val IMG = "/dev/launcherfork/mock"

    /** Mock images ship on the classpath; the domain only sees the resulting URI. */
    private fun res(path: String): URI =
        requireNotNull(MockData::class.java.getResource(path)) { "Missing mock image $path" }.toURI()

    val servers: List<Server> = listOf(
        Server(
            id = "stalcraft-x",
            caption = "STALZONE",
            online = true,
            players = 1284,
            // banner text: i18n keys game.stalzone.* (messages_ru / messages_en), resolved by GameBannerController
            description = GameDescription.Keys("game.stalzone"),
            iconUri = Theme.gameIconUri(),
            backgroundUri = res("$IMG/servers/stalcraft_x_bg.jpg"),
            installed = true,
            clientSizeBytes = 18_400_000_000,
        ),
    )
}
